XMP_BASIC = "http://ns.adobe.com/xap/1.0/"
DUBLIN_CORE = "http://purl.org/dc/elements/1.1/"
GPANO = "http://ns.google.com/photos/1.0/panorama/"
IPTC_EXT = "http://iptc.org/std/Iptc4xmpExt/2008-02-29/"
COMPOSITE = "http://cv.iptc.org/newscodes/digitalsourcetype/compositeWithTrainedAlgorithmicMedia"

SCENE_HONESTY = "Reconstructed from one photo, explore within its limits"
PANORAMA_HONESTY = "Generated by AI beyond the photo's edges"
